mod solution;

fn main() {
    let cases = [
    (r#"[2,3,1,1,4]"#, r#"true"#),
    (r#"[3,2,1,0,4]"#, r#"false"#),
    (r#"
[3,2,1,0,4]
"#, r#"false"#),
    (r#"  
[2,3,1,1,4]
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS jump-game");
}
